package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Ticket represents a ticket that can be any JSON value
type Ticket struct {
	Value json.RawMessage
}

// NodeState tracks the node's ID and set of issued tickets
type NodeState struct {
	NodeID     string
	AllNodes   []string
	TicketNums map[int64]bool
}

// UsedTickets stores all ticket numbers globally (across partitions)
var usedTickets = map[int64]bool{}

func main() {
	node := maelstrom.NewNode()

	node.Handle("init", func(ctx go.Context, body interface{}) error {
		initMsg := struct {
			NodeID    string `json:"id"`
			AllNodes  []string `json:"nodes"`
		}{}
		if err := json.Unmarshal(body, &initMsg); err != nil {
			return err
		}

		state := NodeState{
			NodeID:   initMsg.NodeID,
			AllNodes: initMsg.AllNodes,
			TicketNums: make(map[int64]bool),
		}

		fmt.Fprintf(os.Stderr, "Node %s initialized", state.NodeID)
		fmt.Fprintf(os.Stderr, "Total nodes: %d", len(state.AllNodes))

		return nil
	})

	node.Handle("issue", func(ctx go.Context, body interface{}) error {
		req := struct {
			MsgID int `json:"msg_id"`
		}{}
		if err := json.Unmarshal(body, &req); err != nil {
			return err
		}

		ticketNum := getNextTicketNum(&state, ctx)
		state.TicketNums[ticketNum] = true
		usedTickets[ticketNum] = true

		resp := map[string]interface{}{
			"type":             "issued",
			"in_reply_to":      req.MsgID,
			"ticket":            ticketNum,
		}

		return go.Reply(ctx, resp)
	})

	// Handle messages from other nodes (to check state and collect ticket numbers)
	node.Handle("other_node_info", func(ctx go.Context, body interface{}) error {
		// This is not needed since init gives us all node info
		return nil
	})

	node.Send(func() error {
		fmt.Fprintf(os.Stderr, "Starting node %s", state.NodeID)
		return nil
	})

	return node.Run()
}

func getNextTicketNum(state *NodeState, ctx go.Context) int64 {
	nextNum := 0

	// Try to find the minimum unused ticket number from other nodes
	for i, otherNode := range state.AllNodes {
		if i == 0 {
			continue // Skip self for now
		}

		// Send a request to check available tickets on other nodes
		// Use a simple message to ask what tickets are free
		msg := struct {
			Type   string `json:"type"`
			MsgID  int    `json:"msg_id"`
			Query  bool   `json:"query"`
		}{Type: "request_tickets", MsgID: nextNum + 100, Query: true}

		body, err := json.Marshal(msg)
		if err != nil {
			nextNum = 1
			continue
		}

		err = state.sendToNode(body, otherNode, func(result interface{}) error {
			resp := struct {
				Type        string `json:"type"`
				Ticket      int64 `json:"ticket"`
				Available   bool   `json:"available"`
			}{}
			if err := json.Unmarshal(result, &resp); err != nil {
				return nil // Ignore errors for simplicity
			}
			if resp.Available && resp.Type == "available" {
				nextNum = resp.Ticket
			}
			return nil
		})

		// If we can't send to the node (partition), just try incrementing from here
		if err != nil || nextNum == 0 {
			nextNum = 1
			break
		}
	}

	// If we didn't get any info, just return nextNum + some offset
	if nextNum == 0 {
		nextNum = int64(1)
	}

	return nextNum
}

func (s *NodeState) sendToNode(msg interface{}, targetID string, callback func(interface{}) error) error {
	// This function needs to send messages to other nodes
	// We'll use the maelstrom RPC mechanism
	return nil
}

